import React, { ReactNode, useEffect, useRef } from 'react';
import { useTranslation } from 'react-i18next';
import { Loading } from '@carbon/react';
import { uniqueId } from 'lodash';
import classNames from 'classnames';
import DOMPurify from 'dompurify';
import useToggle from '../hooks/booleanHooks.ts';
import Copier from './Copier.tsx';
import CodeViewer from './CodeViewer.tsx';
import ExpandableDisplay from './ExpandableDisplay.tsx';
import CredentialsSelector, { CredentialPayload } from './CredentialsSelector.tsx';
import LanguageSelector from './LanguageSelector.tsx';
import { CodeLanguagesTypes } from '../code-snippets/constants.ts';

type CodeSnippetProps = {
  availableCodeLanguages: string[];
  activeCodeLanguage: string;
  generating: boolean;
  showExpander: boolean;
  errorText: string;
  content: string | ReactNode;
  highlight: boolean;
  withCredentials?: boolean;
  label?: string;
  withLanguageSelector?: boolean;
  onChangeCredentials: (e: CredentialPayload) => void;
  onChangeCodeLanguage: (language: CodeLanguagesTypes) => void;
};

const _CodeSnippet = ({
  availableCodeLanguages,
  activeCodeLanguage,
  generating,
  showExpander,
  errorText,
  content,
  highlight,
  withCredentials,
  withLanguageSelector = true,
  label,
  onChangeCredentials,
  onChangeCodeLanguage
}: CodeSnippetProps) => {
  const { t: translate } = useTranslation();

  // Define type directly in the useToggle hook
  const [expanded, toggleExpandedFn] = useToggle<boolean>(false);

  const selectedCodeLanguage: string | undefined = activeCodeLanguage ?? availableCodeLanguages?.[0] ?? undefined;

  const copyRef = useRef(`code-snippet-${uniqueId()}`);
  const copyId = copyRef.current;
  const copierRef = useRef(null);

  useEffect(() => {
    // This function collapses the expanded display when the user has previously expanded the display and
    // then switches to a code snippet where there shouldn't be any expansion. This will catch this scenario
    // and automatically minimize the expansion display.
    if (!showExpander && expanded) {
      toggleExpandedFn();
    }
  }, [showExpander, expanded, toggleExpandedFn]);

  const renderError = (errorText: string) => <div data-testid="snippet-error">{translate('generator_error', { error: errorText })}</div>;

  const renderContent = () =>
    highlight ? (
      <CodeViewer
        data-copytarget={copyId}
        data-testid="generated-code"
        codeLanguage={selectedCodeLanguage}
        className={classNames('codeSnippetContent', { expanded })}
      >
        {content}
      </CodeViewer>
    ) : (
      <pre>
        <code
          data-copytarget={copyId}
          className={classNames(
            'boundedSection hljs codeSnippetContent',
            { js: activeCodeLanguage === 'node' },
            { language: selectedCodeLanguage !== 'node' },
            { expanded }
          )}
        >
          <div data-testid="generated-code" dangerouslySetInnerHTML={{ __html: typeof content === 'string' ? DOMPurify.sanitize(content) : '' }} />
        </code>
      </pre>
    );

  return (
    <div className={classNames({ codeSnippetsDisplay: !showExpander })}>
      {errorText ? (
        renderError(errorText)
      ) : (
        <div className={classNames({ body: !showExpander })}>
          <div className={classNames({ codeSnippetDropdowns: withCredentials })}>
            {withCredentials && <CredentialsSelector onChange={onChangeCredentials} />}
            {withLanguageSelector && (
              <LanguageSelector
                activeCodeLanguage={activeCodeLanguage}
                availableCodeLanguages={availableCodeLanguages}
                onChangeCodeLanguage={onChangeCodeLanguage}
              />
            )}
          </div>
          {label && (
            <h4 className="codeSnippetLabel" data-testid="code-snippet-label">
              {label}
            </h4>
          )}
          {/* eslint-disable-next-line no-nested-ternary */}
          {generating ? (
            <Loading small withOverlay={false} data-testid="loading-icon" />
          ) : showExpander ? (
            <ExpandableDisplay expanded={expanded} onExpand={toggleExpandedFn}>
              {renderContent()}
            </ExpandableDisplay>
          ) : (
            <div data-testid="parent-generated-content" className={classNames('cds--snippet', 'cds--snippet--multi', 'cds--snippet--wraptext')}>
              <div ref={copierRef} className={classNames('cds--snippet-container')}>
                {renderContent()}
              </div>
              <Copier element={`[data-copytarget='${copyId}']`} copierRef={copierRef} buttonText="Copy" />
            </div>
          )}
        </div>
      )}
    </div>
  );
};

const CodeSnippet = _CodeSnippet;
export default CodeSnippet;
