/* eslint-disable import/no-cycle */

import { get } from 'lodash';
import ApiCommon from './api-common.ts';
import OpenApiV2 from './open-api-v2.ts';
import OpenApiV3 from './open-api-v3.ts';
import { AsyncApi } from './async-api.ts';
import { ODataApi } from './odata-api.ts';

const handleOpenAPI = (api: any): ApiCommon => {
  if (api.openapi) {
    return new OpenApiV3(api);
  }
  if (api.swagger) {
    return new OpenApiV2(api);
  }
  // Fallback to OpenApiV2 if neither openapi nor swagger is present
  return new OpenApiV2(api);
};

const handleAsyncAPI = (api: any): AsyncApi => new AsyncApi(api);

const handleOData = (api: any): ODataApi => new ODataApi(api);

export default function ApiFactory(api: any): ApiCommon {
  if (api) {
    // Check for OData FIRST before OpenAPI, since OData APIs may also have swagger/openapi fields
    if (api?.['x-ibm-configuration']?.type === 'odata') {
      return handleOData(api);
    }
    if (get(api, '_json.asyncapi')) {
      return handleAsyncAPI(api);
    }
    if (api.openapi || api.swagger) {
      return handleOpenAPI(api);
    }
  }

  // Default to Open API version 2.0
  return new OpenApiV2(api);
}
