/**
 * Automatically flips directional align values in LTR / RTL layouts.
 */

export type TooltipAlign =
  | 'top'
  | 'top-left'
  | 'top-right'
  | 'bottom'
  | 'bottom-left'
  | 'bottom-right'
  | 'left'
  | 'left-top'
  | 'left-bottom'
  | 'right'
  | 'right-top'
  | 'right-bottom';
export type LogicalAlign = 'start' | 'end';

/**
 * Check if the document direction is RTL by examining the dir attribute
 * on the apiconnect-explorer-container element
 */
const isRtl = () => {
  const container = document.querySelector('.apiconnect-explorer-container');
  return container?.getAttribute('dir') === 'rtl';
};

export function getBidiAlignAbsolute(a: TooltipAlign): TooltipAlign {
  if (!isRtl()) return a;
  const map: Record<TooltipAlign, TooltipAlign> = {
    top: 'top',
    bottom: 'bottom',
    left: 'right',
    right: 'left',
    'top-left': 'top-right',
    'top-right': 'top-left',
    'bottom-left': 'bottom-right',
    'bottom-right': 'bottom-left',
    'left-top': 'right-top',
    'left-bottom': 'right-bottom',
    'right-top': 'left-top',
    'right-bottom': 'left-bottom'
  };
  return map[a] ?? a;
}

export function getBidiAlignLogical(a: LogicalAlign): LogicalAlign {
  if (!isRtl()) return a;
  const map: Record<LogicalAlign, LogicalAlign> = {
    start: 'end',
    end: 'start'
  };
  return map[a] ?? a;
}

export function getBidiFlip(a: boolean): boolean {
  if (!isRtl()) return a;
  return !a;
}