import React, { useEffect, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { useConfig } from 'contexts/config';
import { useApi } from 'contexts/ApiHandler';
import { Routes, Route, useParams, useNavigate } from 'react-router-dom';
import { apiPath, decodeChannelName } from 'utils/navigation';
import { getAPIType } from 'utils/APITypes';
import Operation from './Operation.tsx';
import Overview from './Overview';
import AsyncApiOperationOverview from './AsyncApiOperationOverview';
import AsyncApiOperationDetail from './AsyncApiOperationDetail.tsx';
import Webhook from './Webhook.tsx';
import Definitions from './Definitions';
import DocumentationPage from './DocumentationPage.tsx';
import GraphQLDisplay from './GraphQLDisplay';
import ODataDisplay from './ODataDisplay';
import ODataEntitySetOverview from './ODataEntitySetOverview';

// This disables the react-hooks/rules-of-hooks linting check because it is incorrectly flagging issues using
// use* hooks inside callbacks. They are actually being used correctly, in components defined under the Routes
// but the linter isn't able to determine this.
/* eslint react-hooks/rules-of-hooks: 0 */

const getDocumentation = (docs, docName) => {
  if (!docs || !Array.isArray(docs)) return null;
  if (docName.includes('/')) {
    const splitDocName = docName.split('/');
    const parent = getDocumentation(docs, splitDocName.shift());
    if (!parent || !parent.docs) return null;
    docName = splitDocName.join('/');
    return getDocumentation(parent.docs, docName);
  }
  return docs.find((doc) => doc.name === docName);
};

const getDefaultRoute = (docsActive, docs, apis) => (docsActive ? `../documentation/${docs[0].name}` : `../${apiPath(apis[0])}/overview`);

function AsyncApiOperationDetailComponent() {
  const { api } = useApi();
  const path = useParams();
  const channel = decodeChannelName(path.channel);
  
  // Check if this is an OData API
  const apiType = getAPIType(api);
  if (apiType === 'OData') {
    return <ODataEntitySetOverview entitySetName={channel} />;
  }
  
  return <AsyncApiOperationOverview channelName={channel} />;
}

function OperationComponent({ apiState, apps, options }) {
  const path = useParams();
  const { apiHandler } = useApi();
  const operationPath = decodeURIComponent(path.path);
  const pathEntry = apiState.currentApi.paths[operationPath];

  // OAS 3.1 allows a path to be a $ref to a pathItem in components/pathItems.
  // Resolve it before reading the method so Operation receives a valid object.
  const resolvedPathEntry = pathEntry?.$ref
    ? apiHandler.getLocalReference(pathEntry.$ref, apiState.currentApi)
    : pathEntry;

  return (
    <Operation
      operation={resolvedPathEntry?.[path.method]}
      operationPath={operationPath}
      operationMethod={path.method}
      apps={apps}
      data-testid="operation"
      options={options}
    />
  );
}

function WebhookComponent({ api }) {
  const { event } = useParams();
  return <Webhook api={api} event={event} />;
}

function ChannelOperationComponent({ apiHandler }) {
  const path = useParams();
  const channel = decodeChannelName(path.channel);
  const operationId = decodeURIComponent(path.operationId);
  const channelType = apiHandler.api.operations().get(operationId).action();
  return <AsyncApiOperationDetail channelName={channel} channelType={channelType} operationId={operationId} />;
}

function ChannelSendComponent() {
  const path = useParams();
  const channel = decodeChannelName(path.channel);
  return <AsyncApiOperationDetail channelName={channel} channelType="publish" />;
}

function ChannelSubscribeComponent() {
  const path = useParams();
  const channel = decodeChannelName(path.channel);
  return <AsyncApiOperationDetail channelName={channel} channelType="subscribe" />;
}

function ChannelPublishComponent() {
  const path = useParams();
  const channel = decodeChannelName(path.channel);
  return <AsyncApiOperationDetail channelName={channel} channelType="publish" />;
}

function DocumentationComponent({ docs, options, apis }) {
  const path = useParams();
  // Combine :docName and * to get the full nested doc path,
  // e.g. "authentication" + "auth_clientid_secret" → "authentication/auth_clientid_secret"
  const docName = [path.docName, path['*']].filter(Boolean).join('/');
  const doc = getDocumentation(docs, docName);
  return <DocumentationPage options={options} apis={apis} doc={doc} />;
}

function ApiDocumentationComponent({ api, options, apis }) {
  const path = useParams();
  const docName = path['*'] || path.docName;
  const doc = getDocumentation(api['x-embedded-doc'], docName);
  return <DocumentationPage options={options} apis={apis} doc={doc} />;
}


function Routing({ apiState }) {
  const { docs, apis, apps, options } = useConfig();
  const { api, apiHandler } = useApi();
  const docsActive = Array.isArray(docs) && docs.length > 0;
  const [defaultRoute, updateDefaultRoute] = useState(() => getDefaultRoute(docsActive, docs, apis));

  const { t } = useTranslation();
  const navigate = useNavigate();

  useEffect(() => {
    const newRoute = getDefaultRoute(docsActive, docs, apis);
    if (newRoute !== defaultRoute) {
      updateDefaultRoute(newRoute);
      // if the defaultRoute changes, we need to redirect incase the current api doesn't exist anymore
      navigate(newRoute);
    }
  }, [apis, docs, docsActive, defaultRoute, navigate]);

  const getOverviewElement = () => {
    const apiType = getAPIType(api);
    if (apiType === 'GraphQL') {
      return (
        <GraphQLDisplay
          options={options}
          api={api}
          infoSectionEntries={apiState.infoSectionEntries}
          documentationEntries={apiState.documentationEntries}
          apps={apps}
        />
      );
    }
    if (apiType === 'OData') {
      return (
        <ODataDisplay
          options={options}
          api={api}
          infoSectionEntries={apiState.infoSectionEntries}
          documentationEntries={apiState.documentationEntries}
          apps={apps}
        />
      );
    }
    return <Overview infoSectionEntries={apiState.infoSectionEntries} documentationEntries={apiState.documentationEntries} />;
  };

  const getTryItElement = () => {
    const apiType = getAPIType(api);
    if (apiType === 'GraphQL') {
      return (
        <GraphQLDisplay
          options={options}
          api={api}
          infoSectionEntries={apiState.infoSectionEntries}
          documentationEntries={apiState.documentationEntries}
          apps={apps}
        />
      );
    }
    if (apiType === 'OData') {
      return (
        <ODataDisplay
          options={options}
          api={api}
          infoSectionEntries={apiState.infoSectionEntries}
          documentationEntries={apiState.documentationEntries}
          apps={apps}
        />
      );
    }
    return <Overview infoSectionEntries={apiState.infoSectionEntries} documentationEntries={apiState.documentationEntries} />;
  };

  return (
    <Routes>
      <Route path="overview" element={getOverviewElement()} />
      <Route path="try-it" element={getTryItElement()} />
      <Route path="operation/:path/:method" element={<OperationComponent apiState={apiState} apps={apps} options={options} />} />
      <Route path="webhook/:event" element={<WebhookComponent api={api} />} />
      <Route path="definitions" element={<Definitions options={options} api={api} infoSectionEntries={apiState.infoSectionEntries} />} />
      <Route path=":channel/overview" element={<AsyncApiOperationDetailComponent />} />
      <Route path=":channel/operation/:operationId" element={<ChannelOperationComponent apiHandler={apiHandler} />} />
      <Route path=":channel/send" element={<ChannelSendComponent />} />
      <Route path=":channel/subscribe" element={<ChannelSubscribeComponent />} />
      <Route path=":channel/publish" element={<ChannelPublishComponent />} />
      <Route path="documentation/*" element={<ApiDocumentationComponent api={api} options={options} apis={apis} />} />
      {docs && docs.length > 0 && <Route path=":docName/*" element={<DocumentationComponent docs={docs} options={options} apis={apis} />} />}
      <Route path="*" element={<div data-testid="404Error">{t('error_404')}</div>} />
    </Routes>
  );
}

export default Routing;
