import React, { useEffect, useState } from 'react';
import { TextInput, PasswordInput } from '@carbon/react';
import { useTranslation } from 'react-i18next';
import DOMPurify from 'dompurify';

type UserCreds = {
  username?: string;
  password?: string;
};

type TestToolUserCredentialsProps = {
  userCreds: UserCreds;
  // eslint-disable-next-line
  onChange?: (creds: UserCreds) => void;
};

const TestToolUserCredentials: React.FC<TestToolUserCredentialsProps> = ({ userCreds, onChange }) => {
  const { t } = useTranslation();
  const [username, setUsername] = useState<string>('');
  const [password, setPassword] = useState<string>('');

  useEffect(() => {
    setUsername(userCreds.username ?? '');
    setPassword(userCreds.password ?? '');
  }, [userCreds.password, userCreds.username]);

  const handleUsernameChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const username = event.target.value;
    setUsername(username);
    if (onChange && typeof onChange === 'function') {
      onChange({ password, username });
    }
  };

  const handlePasswordChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const password = event.target.value;
    setPassword(password);
    if (onChange && typeof onChange === 'function') {
      onChange({ password, username });
    }
  };

  return (
    <div className="testToolUserCredentials">
      <div className="username">
        <div className="securityHeader">
          <div className="labelText">{t('username')}</div>
          <div className="requiredHighlight parameterIn">{t('required')}</div>
        </div>
        <TextInput id="username" hideLabel labelText={t('username')} value={DOMPurify.sanitize(username)} onChange={handleUsernameChange} />
      </div>

      <div className="password">
        <div className="securityHeader">
          <div className="labelText">{t('password')}</div>
          <div className="requiredHighlight parameterIn">{t('required')}</div>
        </div>
        <PasswordInput id="password" labelText={t('password')} hideLabel value={password} onChange={handlePasswordChange} />
      </div>
    </div>
  );
};

export default TestToolUserCredentials;
