import React, { useMemo, useContext } from 'react';
import { I18nextProvider } from 'react-i18next';
import ConfigProvider, { ConfigContext } from 'contexts/config';
import App from 'App';
import initI18n from 'utils/i18n';
import { Theme } from '@carbon/react';
import 'css/main.scss';

function I18nWrapper({ children }) {
  const config = useContext(ConfigContext);
  const i18n = useMemo(
    () => initI18n({ explorerDir: config.options.explorerDir, locale: config.options.locale }),
    [config.options.explorerDir, config.options.locale]
  );

  return (
    <div dir={i18n.dir()} className="apiconnect-explorer-container">
      <I18nextProvider i18n={i18n}>
        {children}
      </I18nextProvider>
    </div>
  );
}

// Map Carbon theme tokens to light/dark mode class
const themeToMode = { white: 'light', g10: 'light', g90: 'dark', g100: 'dark' };

function ExplorerContent() {
  const config = useContext(ConfigContext);
  const theme = config.options?.theme || 'white';
  const mode = themeToMode[theme] ?? 'light';
  const themeClassName = `apic-explorer-${mode}`;

  return (
    <Theme theme={theme} className={themeClassName}>
        <I18nWrapper>
          <App />
        </I18nWrapper>
    </Theme>
  );
}

function ApiExplorer({ options, apis, encodedApis, apps, docs }) {
  return (
    <ConfigProvider options={options} apis={apis} encodedApis={encodedApis} apps={apps} docs={docs}>
      <ExplorerContent />
    </ConfigProvider>
  );
}

export default ApiExplorer;
