import React, { useEffect, useState, useRef, useMemo } from 'react';
import { get } from 'lodash';
import { useApi } from '../contexts/ApiHandler/index.tsx';
import { useConfig } from '../contexts/config';
import CodeSnippet from './CodeSnippet.tsx';
import { isExpandable } from '../utils/common';
import { getGeneratedOptionsForOperation, generateOperationContent } from '../code-snippets/CodeSnippetGenerator';
import { CodeLanguagesTypes } from '~/code-snippets/constants.ts';
import { SnippetInfoType } from '~/utils/common-interfaces/common-interfaces.ts';

const defaultConfig = {
  requiresClientId: false,
  clientIdLocation: null,
  clientIdName: null,
  requiresClientSecret: false,
  clientSecretLocation: null,
  clientSecretName: null,
  requiresBasicAuth: false,
  requiresDigestAuth: false,
  requiresHobaAuth: false,
  requiresScramShaAuth: false,
  requiresVapidAuth: false,
  requiresNegotiateAuth: false,
  requiresMutualAuth: false,
  requiresOauth: false,
  parametersArray: [],
  externalApiKeys: {},
  soapAction: null,
  contenttype: null,
  accept: null,
  selectedSecurityOption: 0
};

type CodeSnippetsDisplayProps = {
  snippetType: string;
  snippetInfo: SnippetInfoType;
}

const CodeSnippetsDisplay = ({ snippetType, snippetInfo }: CodeSnippetsDisplayProps) => {
  const { api, apiHandler }: any = useApi();

  const configContext = useConfig();
  const config = useMemo(() => ({ ...defaultConfig, ...configContext, ...get(snippetInfo, 'config') }), [configContext, snippetInfo]);
  const codeLanguages = get(config, 'options.languages');
  const defaultCodeLanguage = get(config, 'options.defaultLanguage');

  const [codeLanguage, updateCodeLanguage] = useState<string>(defaultCodeLanguage ?? '');
  const [generating, updateGenerating] = useState<boolean>(true);
  const [operationSnippets, updateOperationSnippets] = useState<Record<string, any>>({})
  const [errorText, updateErrorText] = useState<string | null>(null);
  const _isMounted = useRef(false);

  useEffect(() => {
    _isMounted.current = true;
    return () => {
      _isMounted.current = false;
    };
  }, []);

  const handleCodeSnippet = (data: any, error: string | null) => {
    if (_isMounted.current) {
      if (data) {
        updateGenerating(false);
        updateOperationSnippets(data);
      } else if (error) {
        updateGenerating(false);
        updateErrorText(error);
      }
    }
  };

  useEffect(() => {
    if (snippetInfo && api) {
      let generatorOptions = null;

      if (snippetType === 'operation' && snippetInfo.operation && snippetInfo.pathName) {
        const { operation, pathName, method, maxDepth } = snippetInfo;
        generatorOptions = getGeneratedOptionsForOperation(config, operation, pathName, method, codeLanguages, maxDepth, api, apiHandler);
      }

      if (generatorOptions && snippetType === 'operation') {
        handleCodeSnippet(generateOperationContent(generatorOptions).snippets, '');
      }
    } else {
      handleCodeSnippet(null, 'Invalid snippet configuration');
    }
  }, [snippetInfo, snippetType, config, api, apiHandler, codeLanguages]);

  useEffect(() => {
    if (_isMounted.current && codeLanguages && (!codeLanguages.includes(codeLanguage) || (!codeLanguage && !defaultCodeLanguage))) {
      updateCodeLanguage(codeLanguages[0]);
    }
  }, [codeLanguage, defaultCodeLanguage, codeLanguages]);

  const changeCodeLanguage = (newValue: CodeLanguagesTypes) => {
    if (_isMounted.current) {
      updateCodeLanguage(newValue);
    }
  };

  let content;
  if (operationSnippets && operationSnippets[`${codeLanguage}Content`]) {
    content = operationSnippets[`${codeLanguage}Content`];
  } else if (errorText) {
    content = errorText;
  }

  const largeContent = isExpandable(content, 8);

  // eslint-disable-next-line react/jsx-boolean-value
  return <CodeSnippet availableCodeLanguages={codeLanguages ?? []} activeCodeLanguage={codeLanguage} generating={generating} showExpander={largeContent} errorText={errorText ?? ''} content={content} highlight={true} onChangeCredentials={() => {}} onChangeCodeLanguage={changeCodeLanguage} />;
}

export default CodeSnippetsDisplay;
