import React from 'react';
import { useTranslation } from 'react-i18next';
import { Link } from 'react-router-dom';
import parse, { domToReact, HTMLReactParserOptions, DOMNode, Element } from 'html-react-parser';
import { CodeSnippet } from '@carbon/react';
import classNames from 'classnames';
import DOMPurify from 'dompurify';
import { cleanUpKey, b64DecodeUnicode } from '../utils/common';
import { getTranslatedExtensions } from '../utils/translate';
import { apiPath } from '../utils/navigation';

// Define Markdown component
type MarkdownProps = {
  data: string;
  className: string;
};

const Markdown = ({ data, className }: MarkdownProps): React.ReactElement => (
  <div className={className} dangerouslySetInnerHTML={{ __html: DOMPurify(window).sanitize(data) }} />
);

type ApiInfo = {
  title?: string;
  summary?: string;
  description?: string;
  version?: string;
  'x-ibm-summary'?: string;
}

type Api = {
  id: string;
  info: ApiInfo;
}

type Doc = {
  title?: string;
  content?: string;
  format?: string;
  docs?: Doc[];
}

type DocumentationPageProps = {
  options?: Record<string, unknown>;
  apis: Api[];
  doc?: Doc;
}

let copyEnabled = false;
if (typeof document !== 'undefined' && document.queryCommandSupported) {
  copyEnabled = document.queryCommandSupported('copy');
}

// Helper function for copying text
const copyTextHelper = (parm: string): void => {
  if (parm) {
    const elementNode = document.getElementById(parm);

    if (!elementNode) {
      // Can't proceed
      return;
    }

    // select and copy
    const range = document.createRange();
    range.selectNodeContents(elementNode);
    const sel = window.getSelection();
    if (sel) {
      sel.removeAllRanges();
      sel.addRange(range);

      // we've at least selected the text... but
      if (copyEnabled) {
        // we can also copy straight to the clipboard
        document.execCommand('copy');
        sel.removeAllRanges();
      }
    }
  }
};

interface ApisListProps {
  apis: Api[];
}

function ApisList({ apis }: ApisListProps): React.ReactElement {
  // Create a simple markdown remover function
  const rmmd = (text: string): string => text
    .replace(/#+\s+(.*)/g, '$1')
    .replace(/\*\*(.*)\*\*/g, '$1')
    .replace(/\*(.*)\*/g, '$1')
    .replace(/\[(.*)\]\(.*\)/g, '$1')
    .replace(/`(.*)`/g, '$1')
    .replace(/~~(.*)~~/g, '$1')
    .replace(/>\s+(.*)/g, '$1')
    .replace(/\n/g, ' ');
  
  return (
    <div className="apic-explorer_apis">
      {apis.map((api, index) => {
        const summary = api.info && (api.info.summary || api.info['x-ibm-summary']);
        const description = api.info && api.info.description;
        return (
          <section key={`${api.id + index}`} className="apic-explorer_api">
            <h3>
              <Link to={`/${apiPath(api)}/overview`} className="api-title">
                {getTranslatedExtensions(api.info, 'title')}
              </Link>
            </h3>
            <caption className="cds--type-caption">{api.info.version}</caption>
            <div className="apiDescription">{summary ? rmmd(summary) : description && rmmd(description)}</div>
          </section>
        );
      })}
    </div>
  );
}

type CodeSnippetComponentProps = {
  id: string;
  children: React.ReactNode;
  onClick: () => void;
}

function CodeSnippetComponent({ id, children, onClick }: CodeSnippetComponentProps): React.ReactElement {
  return (
    <CodeSnippet
      type="multi"
      onClick={onClick}
      aria-label="Code Snippet Text"
      data-id={id} // Use data attribute instead of id
    >
      {children}
    </CodeSnippet>
  );
}

// Create parser options for HTML parsing
function createParserOptions(apis: Api[]): HTMLReactParserOptions {
  // Process DOM nodes during HTML parsing
  function handleDomNode(domNode: DOMNode): React.ReactElement | undefined {
    if (!(domNode instanceof Element) || !domNode.attribs) return undefined;

    if (domNode.attribs.class === 'show-explorer-apis') {
      return <ApisList apis={apis} />;
    }
    
    if (domNode.attribs.class === 'show-explorer-codesnippet') {
      const snippetId = domNode.attribs.id;
      
      return (
        <CodeSnippetComponent
          id={snippetId}
          onClick={() => copyTextHelper(snippetId)}
        >
          {domNode.children && domNode.children.length > 0 && domToReact(domNode.children as any)}
        </CodeSnippetComponent>
      );
    }
    return undefined;
  }

  return {
    replace: handleDomNode
  };
}

function DocumentationPage({ apis, doc }: DocumentationPageProps): React.ReactElement {
  const { t } = useTranslation();
  
  
  const getContent = (docObj?: Doc): Doc | null => {
    if (docObj && docObj.content !== undefined && docObj.content.length > 0) {
      return docObj;
    }
    if (docObj && docObj.docs && docObj.docs.length > 0) {
      return getContent(docObj.docs[0]);
    }
    return null;
  };

  let title = t('apic_connect_apis');

  if (doc && doc.title) {
    title = getTranslatedExtensions(doc, 'title');
  }

  let content = `<div class="apic-explorer-docpage_title">
        <h2 class="apic-explorer-docpage_title-text">
          <span class="explorer-doc--header">
            No content to display
          </span>
        </h2>
      </div>`;
  let htmlContent: string | null = null;
  let format = 'md';

  const docPage = getContent(doc);

  if (docPage) {
    const docformat = getTranslatedExtensions(docPage, 'format');

    // if base64 encoded assume html
    if (docformat === 'b64html') {
      htmlContent = b64DecodeUnicode(getTranslatedExtensions(docPage, 'content'));
      format = 'b64html';
    } else {
      content = getTranslatedExtensions(docPage, 'content');
    }
  }

  // Create parser options using the factory
  const parserOptions = createParserOptions(apis);

  return (
    <div className={classNames('apiconnect-explorer', 'apic-explorer--docpage', `apic-explorer--docpage_${cleanUpKey(title)}`)}>
      {format === 'b64html' && htmlContent && parse(DOMPurify(window).sanitize(htmlContent, { USE_PROFILES: { html: true }, FORBID_TAGS: ['script', 'iframe', 'object', 'embed', 'form'], ALLOWED_URI_REGEXP: /^(?:(?:https?|mailto|ftp|tel|file|sms):|[^&:/?#]*(?:[/?#]|$))/i }), parserOptions)}
      {format === 'md' && content && (
        <Markdown
          data={content}
          className=""
        />
      )}
    </div>
  );
}

export default DocumentationPage;
