/* eslint-disable no-unused-vars */
/* eslint-disable camelcase */
import { has } from 'lodash';

declare global {
  interface Window {
    apiConnectExplorer?: any;
    drupalSettings?: {
      api?: {
        explorer?: any;
      };
    };
    Drupal?: {
      settings?: {
        api?: {
          explorer?: any;
        };
      };
    };
  }
}

let config = window.apiConnectExplorer || null;

if (has(window, 'drupalSettings.api.explorer')) {
  config = window.drupalSettings?.api?.explorer;
} else if (has(window, 'Drupal.settings.api.explorer')) {
  // support for Drupal7 style Drupal.settings
  config = window.Drupal?.settings?.api?.explorer;
} // Use props instead if provided
// eslint-disable-next-line no-unused-vars
/* global __webpack_public_path__:writable */
declare let __webpack_public_path__: string;
// eslint-disable-next-line prefer-const
__webpack_public_path__ = config?.options?.explorerDir || '/';
