import { useState } from 'react';

/**
 * A hook that provides toggle functionality with proper TypeScript typing
 * @param initialValue The initial boolean value
 * @returns A tuple containing the current state and a toggle function
 */
const useToggle = <T extends boolean>(initialValue: T): [T, () => void] => {
  const [enabled, update] = useState<T>(initialValue);

  const toggle = () => {
    update((prev: T) => (!prev as unknown) as T);
  };
  
  return [enabled, toggle];
};

export default useToggle;
