const workerUrl = new URL('apiconnect-example-generator/worker', import.meta.url);
let worker = null;
const queue = []; // FIFO — each entry is { resolve, reject }

function getWorker() {
  if (worker) return worker;
  // Worker is intentionally never terminated — it is reused for the session lifetime.
  worker = new Worker(workerUrl);
  worker.onmessage = function handleWorkerMessage(event) {
    const entry = queue.shift();
    if (!entry) return;
    if (event.data != null && event.data.error) {
      entry.reject(event.data.error);
    } else {
      entry.resolve(event.data);
    }
  };
  worker.onerror = function handleWorkerError(error) {
    // Drain pending queue on hard crash; allow recreation on next call
    queue.splice(0).forEach(e => e.reject(error));
    worker = null;
  };
  return worker;
}

export default function sendWorkerData(data) {
  return new Promise((resolve, reject) => {
    queue.push({ resolve, reject });
    getWorker().postMessage(data);
  });
}
