enum ProtocolTypes {
  kafka='kafka',
  kafkaSecure='kafka-secure'
}

const displayType = (type: ProtocolTypes) => {
  switch (type) {
    case ProtocolTypes.kafka:
    case ProtocolTypes.kafkaSecure:
      return 'Kafka';
    default:
      return type;
  }
};

const isKafka = (type: ProtocolTypes) => type === ProtocolTypes.kafka || type === ProtocolTypes.kafkaSecure;
const isKafkaSecure = (type: ProtocolTypes) => type === ProtocolTypes.kafkaSecure;

export { ProtocolTypes, displayType, isKafka, isKafkaSecure };
